\begin{proposition}
\label{proposition-cd-affine}
Let $K$ be a field. Let $X$ be an affine scheme of finite type over $K$.
Then we have $\text{cd}(X) \leq \dim(X) + \text{cd}(K)$.
\end{proposition}

